import { useState, useEffect } from 'react';
import styles from './InvestmentForm.module.css';

const InvestmentForm = ({ onAddInvestment }) => {
  const [formData, setFormData] = useState({
    brand: '',
    processor: '',
    generation: '',
    initialCost: '',
    salePrice: '',
    isSplit: false,
    status: 'pending' // 'pending' o 'sold'
  });
  
  const [investments, setInvestments] = useState([]);
  const [editingId, setEditingId] = useState(null);

  const brands = ['Lenovo', 'HP', 'Acer', 'Fujitsu', 'Dell', 'MSI', 'Asus', 'Gateway', 'Lenovo ThinkPad'];
  const processors = ['Intel Celeron', 'Intel Core i3', 'Intel Core i5', 'Intel Core i7', 'Intel Core i9', 'AMD Ryzen 3', 'AMD Ryzen 5', 'AMD Ryzen 7', 'AMD Ryzen 9'];
  const generations = Array.from({ length: 11 }, (_, i) => i + 4);

  useEffect(() => {
    const savedInvestments = JSON.parse(localStorage.getItem('investments')) || [];
    setInvestments(savedInvestments);
  }, []);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleStatusChange = (e) => {
    setFormData(prev => ({
      ...prev,
      status: e.target.value,
      salePrice: e.target.value === 'pending' ? '' : prev.salePrice
    }));
  };

  const calculateProfit = () => {
    const initialCost = parseFloat(formData.initialCost) || 0;
    const salePrice = parseFloat(formData.salePrice) || 0;
    let profit = salePrice - initialCost;
    
    if (formData.isSplit && formData.status === 'sold') {
      profit = profit / 2;
    }
    
    return profit;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    const initialCost = parseFloat(formData.initialCost) || 0;
    const salePrice = parseFloat(formData.salePrice) || 0;
    const profit = formData.status === 'sold' ? calculateProfit() : 0;

    const investmentDate = new Date().toISOString();

    const newInvestment = {
      ...formData,
      id: editingId || Date.now(),
      date: investmentDate,
      initialCost,
      salePrice: formData.status === 'pending' ? null : salePrice,
      profit: formData.status === 'pending' ? null : profit,
      lastUpdated: investmentDate
    };

    let updatedInvestments;
    if (editingId) {
      updatedInvestments = investments.map(inv => 
        inv.id === editingId ? newInvestment : inv
      );
      setEditingId(null);
    } else {
      updatedInvestments = [newInvestment, ...investments];
    }

    setInvestments(updatedInvestments);
    localStorage.setItem('investments', JSON.stringify(updatedInvestments));

    if (formData.status === 'sold') {
      const currentFinance = JSON.parse(localStorage.getItem('financialData')) || {
        totalIncome: 0,
        totalExpenses: 0,
        balance: 0,
        currentBalance: 0,
      };

      const updatedFinance = {
        ...currentFinance,
        totalIncome: (currentFinance.totalIncome || 0) + salePrice,
        totalExpenses: (currentFinance.totalExpenses || 0) + initialCost,
        balance: (currentFinance.balance || 0) + profit,
        currentBalance: (currentFinance.currentBalance || 0) + profit,
      };

      localStorage.setItem('financialData', JSON.stringify(updatedFinance));
    }

    onAddInvestment && onAddInvestment(newInvestment);

    setFormData({
      brand: '',
      processor: '',
      generation: '',
      initialCost: '',
      salePrice: '',
      isSplit: false,
      status: 'pending'
    });
  };

  const handleSell = (id) => {
    const investmentToSell = investments.find(inv => inv.id === id);
    if (investmentToSell) {
      setFormData({
        ...investmentToSell,
        status: 'sold',
        salePrice: investmentToSell.salePrice || '',
        isSplit: false
      });
      setEditingId(id);
    }
  };

  const handleDelete = (id) => {
    const filteredInvestments = investments.filter(investment => investment.id !== id);
    setInvestments(filteredInvestments);
    localStorage.setItem('investments', JSON.stringify(filteredInvestments));
  };

  return (
    <div className={styles.container}>
      <form className={styles.form} onSubmit={handleSubmit}>
        <h2>{editingId ? 'Actualizar Venta' : 'Registrar Inversión'}</h2>
        
        <select 
          name="brand" 
          value={formData.brand} 
          onChange={handleChange} 
          required
        >
          <option value="" disabled>Selecciona una marca</option>
          {brands.map((brand, index) => (
            <option key={index} value={brand}>{brand}</option>
          ))}
        </select>
        
        <select 
          name="processor" 
          value={formData.processor} 
          onChange={handleChange} 
          required
        >
          <option value="" disabled>Selecciona un procesador</option>
          {processors.map((processor, index) => (
            <option key={index} value={processor}>{processor}</option>
          ))}
        </select>
        
        <select 
          name="generation" 
          value={formData.generation} 
          onChange={handleChange} 
          required
        >
          <option value="" disabled>Selecciona una generación</option>
          {generations.map((generation) => (
            <option key={generation} value={generation}>{generation}ª Generación</option>
          ))}
        </select>
        
        <input
          type="number"
          name="initialCost"
          placeholder="Costo Inicial"
          value={formData.initialCost}
          onChange={handleChange}
          required
          min="0"
          step="0.01"
        />
        
        <div className={styles.statusGroup}>
          <label>
            <input
              type="radio"
              name="status"
              value="pending"
              checked={formData.status === 'pending'}
              onChange={handleStatusChange}
            />
            Pendiente de venta
          </label>
          <label>
            <input
              type="radio"
              name="status"
              value="sold"
              checked={formData.status === 'sold'}
              onChange={handleStatusChange}
            />
            Vendida
          </label>
        </div>
        
        {formData.status === 'sold' && (
  <div className={styles.saleDetails}>
    <input
      type="number"
      name="salePrice"
      placeholder="Precio de venta"
      value={formData.salePrice}
      onChange={handleChange}
      required
      min="0"
      step="0.01"
    />
    
    <label className={styles.splitCheckbox}>
      <input
        type="checkbox"
        name="isSplit"
        checked={formData.isSplit}
        onChange={handleChange}
      />
      Dividir ganancia entre 2 personas
    </label>
    
    {formData.isSplit && formData.salePrice && formData.initialCost && (
      <div className={styles.splitInfo}>
        <p>Ganancia por persona: ${(
          (parseFloat(formData.salePrice) - parseFloat(formData.initialCost)) / 2
        ).toFixed(2)}</p>
      </div>
    )}
  </div>
)}
        
        <button type="submit">
          {editingId ? 'Actualizar Venta' : 'Agregar Inversión'}
        </button>
      </form>

      <div className={styles.investmentsList}>
        {investments.map((investment) => (
          <div 
            key={investment.id} 
            className={`${styles.card} ${
              investment.status === 'pending' ? styles.pending : styles.sold
            }`}
          >
            <h3>
              Inversión #{investment.id.toString().slice(-4)}
              <span className={styles.statusBadge}>
                {investment.status === 'pending' ? 'Pendiente' : 'Vendida'}
              </span>
            </h3>
            
            <p><strong>Marca:</strong> {investment.brand}</p>
            <p><strong>Procesador:</strong> {investment.processor}</p>
            <p><strong>Generación:</strong> {investment.generation}ª</p>
            <p><strong>Costo Inicial:</strong> ${investment.initialCost.toFixed(2)}</p>
            
            {investment.status === 'sold' && (
              <>
                <p><strong>Precio de Venta:</strong> ${investment.salePrice?.toFixed(2)}</p>
                <p className={investment.profit >= 0 ? styles.profit : styles.loss}>
                  <strong>Ganancia{investment.isSplit ? ' (por persona)' : ''}:</strong> 
                  ${investment.profit?.toFixed(2)}
                </p>
                {investment.isSplit && (
                  <p className={styles.splitNote}>* Ganancia dividida entre 2 personas</p>
                )}
              </>
            )}
            
            <div className={styles.cardFooter}>
              <small>{new Date(investment.date).toLocaleString()}</small>
              <div className={styles.actionButtons}>
                {investment.status === 'pending' && (
                  <button 
                    onClick={() => handleSell(investment.id)}
                    className={styles.sellButton}
                  >
                    Registrar Venta
                  </button>
                )}
                <button 
                  onClick={() => handleDelete(investment.id)}
                  className={styles.deleteButton}
                >
                  Eliminar
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default InvestmentForm;
